/// Substitutes `{name}` placeholders in a message.
///
/// # This is the only sanctioned way to build a message
///
/// `NOCTUA.md §9.9` rule 1: never assemble a sentence from fragments. Word
/// order, gender and agreement all differ between languages, and two
/// concatenated lookups that read correctly in English can be ungrammatical
/// or meaningless once translated. A whole sentence with a hole in it
/// survives translation; two halves do not. A source gate enforces it.
///
/// An unknown placeholder is left as it is, braces included, so a missing
/// argument is visible on the page rather than silently blank.
#[must_use]
pub fn fill(template: &str, arguments: &[(&str, &str)]) -> alloc::string::String {
    use alloc::string::String;

    let mut out = String::with_capacity(template.len());
    let mut rest = template;
    while let Some(open) = rest.find('{') {
        out.push_str(&rest[..open]);
        rest = &rest[open + 1..];
        let Some(close) = rest.find('}') else {
            out.push('{');
            break;
        };
        let name = &rest[..close];
        if let Some((_, value)) = arguments.iter().find(|(key, _)| *key == name) {
            out.push_str(value);
        } else {
            // Left as it is, braces included, so a missing argument is
            // visible on the page rather than a silent gap in a sentence.
            out.push('{');
            out.push_str(name);
            out.push('}');
        }
        rest = &rest[close + 1..];
    }
    out.push_str(rest);
    out
}
